<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import { PageHeader } from './ui';
	import AttendanceImport from './AttendanceImport.svelte';
	import { workSession } from './session';
	const session=workSession();
	import { uiText as t, localeTag } from './i18n';
	type Entry={id:string;full_name:string;employee_code:string|null;date:string;checked_in_at:string|null;checked_out_at:string|null;location_name:string;status:string};
	let offset=$state(0),exporting=$state(false);
	let entries=$state<Entry[]>([]),month=$state(new Date().toLocaleDateString('sv-SE').slice(0,7)),search=$state(''),loading=$state(true),error=$state('');
	let filtered=$derived(entries.filter(entry=>`${entry.full_name} ${entry.employee_code??''} ${entry.location_name}`.toLocaleLowerCase(localeTag()).includes(search.toLocaleLowerCase(localeTag()))));
	async function load(){loading=true;error='';try{entries=await request<Entry[]>(`/v1/admin/attendances?month=${encodeURIComponent(month)}&offset=${offset}&search=${encodeURIComponent(search)}`);}catch(cause){error=cause instanceof Error?cause.message:t('Data tidak dapat dimuat.');}finally{loading=false;}}
	async function exportCsv(){exporting=true;error='';try{const all:Entry[]=[];for(let position=0;;position+=200){const batch=await request<Entry[]>(`/v1/admin/attendances?month=${encodeURIComponent(month)}&offset=${position}&search=${encodeURIComponent(search)}`);all.push(...batch);if(batch.length<200)break;} const cell=(value:string)=>`"${(/^[=+@-]/.test(value)?"'":'')+value.replaceAll('"','""')}"`;const rows=[[t('Karyawan'),t('Tanggal'),t('Masuk'),t('Pulang'),t('Lokasi')],...all.map(entry=>[entry.full_name,entry.date,entry.checked_in_at??'',entry.checked_out_at??'',entry.location_name])];const blob=new Blob(['\ufeff'+rows.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`attendance-${month}.csv`;link.click();URL.revokeObjectURL(url);}catch(cause){error=cause instanceof Error?cause.message:t('Ekspor gagal.');}finally{exporting=false;}}
	onMount(load);
</script>
<svelte:head><title>{t('Log Presensi')} · PasPapan</title></svelte:head>
<main class="workspace-page attendance-log" id="main-content" tabindex="-1"><PageHeader title={t('Log Presensi')} description={t('Catatan kehadiran dalam zona waktu perusahaan.')} backHref="/admin/dashboard">{#snippet actions()}<button class="quiet" disabled={!filtered.length||loading||exporting} onclick={exportCsv}>{t('Ekspor CSV')}</button>{/snippet}</PageHeader>{#if error}<p role="alert">{error}</p>{/if}<div class="filters"><label>{t('Bulan')}<input type="month" bind:value={month} onchange={()=>{offset=0;void load();}}/></label><label>{t('Cari karyawan')}<input type="search" bind:value={search} onchange={()=>{offset=0;void load();}}/></label></div>{#if session.current?.capabilities.includes('admin.attendances.manage')}<AttendanceImport/>{/if}<section class="panel" aria-busy={loading}>{#if loading}<p role="status">{t('Memuat…')}</p>{:else if !filtered.length&&!error}<div class="empty"><h2>{t('Belum ada catatan kehadiran')}</h2></div>{:else}<p class="muted">{offset+1}–{offset+entries.length}</p>{#each filtered as entry(entry.id)}<article class="attendance-row"><div><strong>{entry.full_name}</strong><small>{entry.employee_code??'—'} · {entry.date}</small></div><div class="times"><span>{t('Masuk')} <b>{entry.checked_in_at??'—'}</b></span><span>{t('Pulang')} <b>{entry.checked_out_at??'—'}</b></span></div><span class="location">{entry.location_name==='Lokasi kerja'?t('Lokasi kerja'):entry.location_name}</span><span class="badge">{t(entry.status)}</span></article>{/each}{/if}</section><nav aria-label={t('Halaman presensi')}><button class="quiet" disabled={loading||offset===0} onclick={()=>{offset=Math.max(0,offset-200);void load();}}>{t('Sebelumnya')}</button><button class="quiet" disabled={loading||entries.length<200} onclick={()=>{offset+=200;void load();}}>{t('Berikutnya')}</button></nav></main>
<style>
	.attendance-log>nav{display:flex;gap:8px;justify-content:flex-end}.attendance-log{display:grid;gap:12px;align-content:start}.filters{display:grid;grid-template-columns:180px minmax(0,1fr);gap:12px}.panel{padding:16px;border-radius:var(--radius);min-width:0}.attendance-row{display:grid;grid-template-columns:minmax(150px,1fr) 200px minmax(100px,1fr) auto;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--line);font-size:12px}.attendance-row:last-child{border:0}.attendance-row small{display:block;color:var(--muted);margin-top:4px;font-size:11px}.times{display:flex;gap:12px;font-variant-numeric:tabular-nums}.times b{display:block;margin-top:4px}.location{color:var(--muted)}.muted{font-size:11px;color:var(--muted)}h2{font-size:15px}@media(max-width:760px){.attendance-row{grid-template-columns:minmax(0,1fr) auto}.location{grid-column:1}.filters{grid-template-columns:1fr 1fr}}
</style>
